SELECT mq.id, mq.member_email, mq.quest_id, mq.status, mq.assigned_date, mq.due_date, mq.completed_at, mq.created_by, mq.profile_id, q.title, q.description, q.type, q.difficulty, q.theme, q.reward, q.urgency, q.due_days FROM tbl_member_quest mq JOIN tbl_quest q ON mq.quest_id = q.quest_id WHERE mq.member_email = #{email} AND mq.assigned_date = #{date} AND q.active = TRUE
AND mq.profile_id = #{profileId}
ORDER BY q.urgency DESC, mq.id ASC

